//! The database of the API: its connection and its tables, one per resource.

use sea_orm::sea_query::Table;
use sea_orm::{ConnectOptions, ConnectionTrait, Database, DatabaseConnection, DbErr, Schema};

use crate::common::settings::Settings;
use crate::entities::author as author_0;
use crate::entities::book as book_1;

/// Connects to the database of DATABASE_URL and creates the tables it does not have, while you develop; use
/// migrations for a real database (Model2DB writes them).
pub async fn connect(settings: &Settings) -> Result<DatabaseConnection, DbErr> {
    let mut options = ConnectOptions::new(settings.database_url.clone());
    options.sqlx_logging(false);
    let database = Database::connect(options).await?;
    create_tables(&database).await?;
    Ok(database)
}

/// Creates the tables that are missing.
pub async fn create_tables(database: &DatabaseConnection) -> Result<(), DbErr> {
    let schema = Schema::new(database.get_database_backend());
    database.execute(&schema.create_table_from_entity(author_0::Entity).if_not_exists().to_owned()).await?;
    database.execute(&schema.create_table_from_entity(book_1::Entity).if_not_exists().to_owned()).await?;
    Ok(())
}

/// Drops every table of the API: for a database only for tests.
pub async fn drop_tables(database: &DatabaseConnection) -> Result<(), DbErr> {
    database.execute(&Table::drop().table(author_0::Entity).if_exists().to_owned()).await?;
    database.execute(&Table::drop().table(book_1::Entity).if_exists().to_owned()).await?;
    Ok(())
}

